def find_zero(xs: list):
    a = -100  # Initial lower bound of the interval
    b = 100   # Initial upper bound of the interval
    tolerance = 1e-7  # Tolerance level

    while (b - a) / 2 > tolerance:
        c = (a + b) / 2
        if poly(xs, c) == 0:
            return c
        elif poly(xs, a) * poly(xs, c) < 0:
            b = c
        else:
