def maximum(arr, k):
    if k == 0:
        return []
    if k == len(arr):
        return sorted(arr)

    def quickselect(nums, k):
        if not nums:
            return []

        pivot = nums[len(nums) // 2]
        left = [x for x in nums if x > pivot]
        middle = [x for x in nums if x == pivot]
        right = [x for x in nums if x < pivot]

        if k <= len(left):
            return quickselect(left, k)
        elif k > len(left) + len(middle):
            return middle + quickselect(right, k - len(left) - len(middle))
        else:
            return left + middle

    max_k = quickselect(arr, k)
    return sorted(max_k)

def get_odd_collatz(n):
    def dfs(num, odd_nums, memo):
        if num in memo:
            return memo[num]
        if num == 1:
            odd_nums.append(1)
            return
        if num % 2 == 0:
            dfs(num // 2, odd_nums, memo)
        else:
            odd_nums.append(num)
            dfs(3 * num + 1, odd_nums, memo)
        memo[num] = odd_nums.copy()
        return

    odd_nums = []
    memo = {}
    dfs(n, odd_nums, memo)
    return sorted(odd_nums)

