def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    @lru_cache(None)
    def dfs(r, c, length):
        if length == 1:
            return [grid[r][c]]

        min_path = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                path = dfs(nr, nc, length - 1)
                if not min_path or path < min_path:
                    min_path = path

        return [grid[r][c]] + min_path

    min_result = []
    for r in range(N):
        for c in range(N):
            result = dfs(r, c, k)
            if not min_result or result < min_result:
                min_result = result

    return list(min_result)

